reate-issue-controls-and-effect","request":"Trace CreateIssue and its API route through route-level controls, repository, issues-unit, or relevant object controls, inherited permission paths, serializer or request validation, and the issue-creation effect. Identify relevant exceptions instead of assuming endpoint-local checks are the whole authorization path.","resource":"The target repository and its issues unit","operation":"Creating an issue","entryHint":"CreateIssue and its API route","premises":[{"text":"The requested target is CreateIssue and its API route in this Gitea revision.","origin":"user"},{"text":"Relevant exceptions must be identified instead of assuming endpoint-local checks are the whole path.","origin":"user"}],"operationId":"create-issue","intent":"behavior"},"duty":{"kind":"guard","question":"Inspect AST-bound access_model.CanBeAssigned at routers/api/v1/repo/issue.go:609; arguments ["ctx","assignee","ctx.Repo.Repository"]. Source relevance and conditions still need interpretation.","symbol":"CanBeAssigned","parentId":"create-issue-controls-and-effect::entry","reason":"Original source is shown. Explain its role and conditions in a local update; citation is not interpretation."},"evidenceIds":["ev-4c50abd6822f6ebdc55d"],"callsiteEvidenceIds":["ev-98a96680dff3cfd848cf"],"existingTargets":[],"relatedDuties":[{"id":"create-issue-controls-and-effect::entry","kind":"entry","question":"Which entry and applicable upstream controls govern this requested path?"},{"id":"create-issue-controls-and-effect::entry","kind":"entry","question":"Which entry and applicable upstream controls govern this requested path?"}],"policy":{"text":"Creating an issue requires write permission to the repository's issues unit. Read permission to the repository alone does not authorize this write.","origin":"user","location":"experimental-user-brief:gitea-issue-policy/v1"},"semanticSupport":"unreviewed","sourceIdentity":{"id":"struct-436039d5ca50fd0f3168d365","path":"models/perm/access/repo_permission.go","startLine":585,"endLine":595}}],"locationTasks":[],"sourceWindows":[{"id":"ev-98a96680dff3cfd848cf","repository":"go-gitea/gitea","sourceRef":"fc28937a8d772fe9e4025c9b5f24d5db4d86610b","path":"routers/api/v1/repo/issue.go","sha256":"44e001ca50ec2b0a73bb0044da995c32c2da6e6438b84f6545d74f766991a27f","startLine":533,"endLine":653,"text":"533 | func CreateIssue(ctx *context.APIContext) {
534 | 	// swagger:operation POST /repos/{owner}/{repo}/issues issue issueCreateIssue
535 | 	// ---
536 | 	// summary: Create an issue. If using deadline only the date will be taken into account, and time of day ignored.
537 | 	// consumes:
538 | 	// - application/json
539 | 	// produces:
540 | 	// - application/json
541 | 	// parameters:
542 | 	// - name: owner
543 | 	//   in: path
544 | 	//   description: owner of the repo
545 | 	//   type: string
546 | 	//   required: true
547 | 	// - name: repo
548 | 	//   in: path
549 | 	//   description: name of the repo
550 | 	//   type: string
551 | 	//   required: true
552 | 	// - name: body
553 | 	//   in: body
554 | 	//   schema:
555 | 	//     "$ref": "#/definitions/CreateIssueOption"
556 | 	// responses:
557 | 	//   "201":
558 | 	//     "$ref": "#/responses/Issue"
559 | 	//   "403":
560 | 	//     "$ref": "#/responses/forbidden"
561 | 	//   "404":
562 | 	//     "$ref": "#/responses/notFound"
563 | 	//   "412":
564 | 	//     "$ref": "#/responses/error"
565 | 	//   "422":
566 | 	//     "$ref": "#/responses/validationError"
567 | 	//   "423":
568 | 	//     "$ref": "#/responses/repoArchivedError"
569 | 
570 | 	form := web.GetForm[*api.CreateIssueOption](ctx)
571 | 	var deadlineUnix timeutil.TimeStamp
572 | 	if form.Deadline != nil && ctx.Repo.Permission.CanWrite(unit.TypeIssues) {
573 | 		deadlineUnix = timeutil.TimeStamp(form.Deadline.Unix())
574 | 	}
575 | 
576 | 	issue := &issues_model.Issue{
577 | 		RepoID:       ctx.Repo.Repository.ID,
578 | 		Repo:         ctx.Repo.Repository,
579 | 		Title:        form.Title,
580 | 		PosterID:     ctx.Doer.ID,
581 | 		Poster:       ctx.Doer,
582 | 		Content:      form.Body,
583 | 		Ref:          form.Ref,
584 | 		DeadlineUnix: deadlineUnix,
585 | 	}
586 | 
587 | 	assigneeIDs := make([]int64, 0)
588 | 	var err error
589 | 	if ctx.Repo.Permission.CanWrite(unit.TypeIssues) {
590 | 		issue.MilestoneID = form.Milestone
591 | 		assigneeIDs, err = issues_model.MakeIDsFromAPIAssigneesToAdd(ctx, form.Assignee, form.Assignees)
592 | 		if err != nil {
593 | 			if user_model.IsErrUserNotExist(err) {
594 | 				ctx.APIError(http.StatusUnprocessableEntity, fmt.Sprintf("Assignee does not exist: [name: %s]", err))
595 | 			} else {
596 | 				ctx.APIErrorInternal(err)
597 | 			}
598 | 			return
599 | 		}
600 | 
601 | 		// Check if the passed assignees is assignable
602 | 		for _, aID := range assigneeIDs {
603 | 			assignee, err := user_model.GetUserByID(ctx, aID)
604 | 			if err != nil {
605 | 				ctx.APIErrorInternal(err)
606 | 				return
607 | 			}
608 | 
609 | 			valid, err := access_model.CanBeAssigned(ctx, assignee, ctx.Repo.Repository)
610 | 			if err != nil {
611 | 				ctx.APIErrorInternal(err)
612 | 				return
613 | 			}
614 | 			if !valid {
615 | 				ctx.APIError(http.StatusUnprocessableEntity, repo_model.ErrUserDoesNotHaveAccessToRepo{UserID: aID, RepoName: ctx.Repo.Repository.Name}.Error())
616 | 				return
617 | 			}
618 | 		}
619 | 	} else {
620 | 		// setting labels is not allowed if user is not a writer
621 | 		form.Labels = make([]int64, 0)
622 | 	}
623 | 
624 | 	if err := issue_service.NewIssue(ctx, ctx.Repo.Repository, issue, form.Labels, nil, assigneeIDs, form.Projects); err != nil {
625 | 		if errors.Is(err, user_model.ErrBlockedUser) {
626 | 			ctx.APIError(http.StatusForbidden, err.Error())
627 | 		} else if errors.Is(err, util.ErrPermissionDenied) || errors.Is(err, util.ErrNotExist) {
628 | 			ctx.APIError(http.StatusBadRequest, err.Error())
629 | 		} else {
630 | 			ctx.APIErrorInternal(err)
631 | 		}
632 | 		return
633 | 	}
634 | 
635 | 	if form.Closed {
636 | 		if err := issue_service.CloseIssue(ctx, issue, ctx.Doer, ""); err != nil {
637 | 			if issues_model.IsErrDependenciesLeft(err) {
638 | 				ctx.APIError(http.StatusPreconditionFailed, "cannot close this issue because it still has open dependencies")
639 | 				return
640 | 			}
641 | 			ctx.APIErrorInternal(err)
642 | 			return
643 | 		}
644 | 	}
645 | 
646 | 	// Refetch from database to assign some automatic values
647 | 	issue, err = issues_model.GetIssueByID(ctx, issue.ID)
648 | 	if err != nil {
649 | 		ctx.APIErrorInternal(err)
650 | 		return
651 | 	}
652 | 	ctx.JSON(http.StatusCreated, convert.ToAPIIssue(ctx, ctx.Doer, issue))
653 | }
