586 | 	if user.IsOrganization() {
587 | 		return false, util.NewInvalidArgumentErrorf("organization can't be added as assignee [user_id: %d, repo_id: %d]", user.ID, repo.ID)
588 | 	}
589 | 	perm, err := GetIndividualUserRepoPermission(ctx, repo, user)
590 | 	if err != nil {
591 | 		return false, err
592 | 	}
593 | 	return perm.CanAccessAny(perm_model.AccessModeWrite, unit.AllRepoUnitTypes...) ||
594 | 		perm.CanAccessAny(perm_model.AccessModeRead, unit.TypePullRequests), nil
595 | }
