","bytes":1104},{"id":"ev-e7b5fe1edaf26dae87f7","repository":"go-gitea/gitea","sourceRef":"fc28937a8d772fe9e4025c9b5f24d5db4d86610b","path":"models/perm/access/access.go","sha256":"ef188452e9ad97857123a2e191f234ce554a68786ec33cffba84327903c23e7d","startLine":38,"endLine":72,"text":"38 | func modeByOwnerAndAccess(ctx context.Context, user *user_model.User, repo *repo_model.Repository) (perm.AccessMode, error) {
39 | 	mode := perm.AccessModeNone
40 | 	var userID int64
41 | 	restricted := false
42 | 
43 | 	if user != nil {
44 | 		userID = user.ID
45 | 		restricted = user.IsRestricted
46 | 	}
47 | 
