52 | 	if issue.IsClosed {
53 | 		return nil, ErrIssueIsClosed{
54 | 			ID:     issue.ID,
55 | 			RepoID: issue.RepoID,
56 | 			Index:  issue.Index,
57 | 			IsPull: issue.IsPull,
58 | 		}
59 | 	}
60 | 
