62 | 	if issue.Repo.IsDependenciesEnabled(ctx) {
63 | 		// only check if dependencies are enabled and we're about to close an issue, otherwise reopening an issue would fail when there are unsatisfied dependencies
64 | 		noDeps, err := IssueNoDependenciesLeft(ctx, issue)
