","bytes":747},{"id":"ev-f052195193cf7c48517c","repository":"go-gitea/gitea","sourceRef":"fc28937a8d772fe9e4025c9b5f24d5db4d86610b","path":"models/issues/issue_update.go","sha256":"9ca2f53fa9285d96f8ccebdf4b4d3c112c1172a4f003a4da752d9ccb0fc9b988","startLine":575,"endLine":696,"text":"575 | func ResolveIssueMentionsByVisibility(ctx context.Context, issue *Issue, doer *user_model.User, mentions []string) (users []*user_model.User, err error) {
576 | 	if len(mentions) == 0 {
577 | 		return nil, nil
578 | 	}
579 | 	if err = issue.LoadRepo(ctx); err != nil {
580 | 		return nil, err
581 | 	}
582 | 
583 | 	resolved := make(map[string]bool, 10)
584 | 	var mentionTeams []string
585 | 
586 | 	if err := issue.Repo.LoadOwner(ctx); err != nil {
587 | 		return nil, err
588 | 	}
589 | 
590 | 	repoOwnerIsOrg := issue.Repo.Owner.IsOrganization()
591 | 	if repoOwnerIsOrg {
592 | 		mentionTeams = make([]string, 0, 5)
593 | 	}
594 | 
595 | 	resolved[doer.LowerName] = true
596 | 	for _, name := range mentions {
597 | 		name := strings.ToLower(name)
598 | 		if _, ok := resolved[name]; ok {
599 | 			continue
600 | 		}
601 | 		if repoOwnerIsOrg && strings.Contains(name, "/") {
602 | 			names := strings.Split(name, "/")
603 | 			if len(names) < 2 || names[0] != issue.Repo.Owner.LowerName {
604 | 				continue
605 | 			}
606 | 			mentionTeams = append(mentionTeams, names[1])
607 | 			resolved[name] = true
608 | 		} else {
609 | 			resolved[name] = false
610 | 		}
611 | 	}
612 | 
613 | 	if issue.Repo.Owner.IsOrganization() && len(mentionTeams) > 0 {
614 | 		teams := make([]*organization.Team, 0, len(mentionTeams))
615 | 		if err := db.GetEngine(ctx).
616 | 			Join("INNER", "team_repo", "team_repo.team_id = team.id").
617 | 			Where("team_repo.repo_id=?", issue.Repo.ID).
618 | 			In("team.lower_name", mentionTeams).
619 | 			Find(&teams); err != nil {
620 | 			return nil, fmt.Errorf("find mentioned teams: %w", err)
621 | 		}
622 | 		if len(teams) != 0 {
623 | 			checked := make([]int64, 0, len(teams))
624 | 			unittype := unit.TypeIssues
625 | 			if issue.IsPull {
626 | 				unittype = unit.TypePullRequests
627 | 			}
628 | 			for _, team := range teams {
629 | 				if team.UnitEnabled(ctx, unittype) {
630 | 					checked = append(checked, team.ID)
631 | 					resolved[issue.Repo.Owner.LowerName+"/"+team.LowerName] = true
632 | 				}
633 | 			}
634 | 			if len(checked) != 0 {
635 | 				teamusers := make([]*user_model.User, 0, 20)
636 | 				if err := db.GetEngine(ctx).
637 | 					Join("INNER", "team_user", "team_user.uid = `user`.id").
638 | 					In("`team_user`.team_id", checked).
639 | 					And("`user`.is_active = ?", true).
640 | 					And("`user`.prohibit_login = ?", false).
641 | 					Find(&teamusers); err != nil {
642 | 					return nil, fmt.Errorf("get teams users: %w", err)
643 | 				}
644 | 				if len(teamusers) > 0 {
645 | 					users = make([]*user_model.User, 0, len(teamusers))
646 | 					for _, user := range teamusers {
647 | 						if already, ok := resolved[user.LowerName]; !ok || !already {
648 | 							users = append(users, user)
649 | 							resolved[user.LowerName] = true
650 | 						}
651 | 					}
652 | 				}
653 | 			}
654 | 		}
655 | 	}
656 | 
657 | 	// Remove names already in the list to avoid querying the database if pending names remain
658 | 	mentionUsers := make([]string, 0, len(resolved))
659 | 	for name, already := range resolved {
660 | 		if !already {
661 | 			mentionUsers = append(mentionUsers, name)
662 | 		}
663 | 	}
664 | 	if len(mentionUsers) == 0 {
665 | 		return users, err
666 | 	}
667 | 
668 | 	if users == nil {
669 | 		users = make([]*user_model.User, 0, len(mentionUsers))
670 | 	}
671 | 
672 | 	unchecked := make([]*user_model.User, 0, len(mentionUsers))
673 | 	if err := db.GetEngine(ctx).
674 | 		Where("`user`.is_active = ?", true).
675 | 		And("`user`.prohibit_login = ?", false).
676 | 		In("`user`.lower_name", mentionUsers).
677 | 		Find(&unchecked); err != nil {
678 | 		return nil, fmt.Errorf("find mentioned users: %w", err)
679 | 	}
680 | 	for _, user := range unchecked {
681 | 		if already := resolved[user.LowerName]; already || user.IsOrganization() {
682 | 			continue
683 | 		}
684 | 		// Normal users must have read access to the referencing issue
685 | 		perm, err := access_model.GetIndividualUserRepoPermission(ctx, issue.Repo, user)
686 | 		if err != nil {
687 | 			return nil, fmt.Errorf("GetIndividualUserRepoPermission [%d]: %w", user.ID, err)
688 | 		}
689 | 		if !perm.CanReadIssuesOrPulls(issue.IsPull) {
690 | 			continue
691 | 		}
692 | 		users = append(users, user)
693 | 	}
694 | 
695 | 	return users, err
696 | }
