","bytes":747},{"id":"ev-01e174787ee76c54fa90","repository":"go-gitea/gitea","sourceRef":"fc28937a8d772fe9e4025c9b5f24d5db4d86610b","path":"models/issues/issue_update.go","sha256":"9ca2f53fa9285d96f8ccebdf4b4d3c112c1172a4f003a4da752d9ccb0fc9b988","startLine":552,"endLine":571,"text":"552 | func FindAndUpdateIssueMentions(ctx context.Context, issue *Issue, doer *user_model.User, content string) (mentions []*user_model.User, err error) {
553 | 	rawMentions := references.FindAllMentionsMarkdown(content)
