557 | 	}
558 | 
559 | 	notBlocked := make([]*user_model.User, 0, len(mentions))
560 | 	for _, user := range mentions {
561 | 		if !user_model.IsUserBlockedBy(ctx, doer, user.ID) {
562 | 			notBlocked = append(notBlocked, user)
563 | 		}
564 | 	}
565 | 	mentions = notBlocked
566 | 
567 | 	if err = UpdateIssueMentions(ctx, issue.ID, mentions); err != nil {
568 | 		return nil, fmt.Errorf("UpdateIssueMentions [%d]: %w", issue.ID, err)
569 | 	}
570 | 	return mentions, err
571 | }
