ty":{"id":"struct-ac2acd7ff22c20f398b4f7a7","path":"models/repo/repo.go","startLine":368,"endLine":383},"receiverClass":"models/repo.Repository"}],"locationTasks":[],"sourceWindows":[{"id":"ev-98a96680dff3cfd848cf","repository":"go-gitea/gitea","sourceRef":"fc28937a8d772fe9e4025c9b5f24d5db4d86610b","path":"routers/api/v1/repo/issue.go","sha256":"44e001ca50ec2b0a73bb0044da995c32c2da6e6438b84f6545d74f766991a27f","startLine":533,"endLine":653,"text":"533 | func CreateIssue(ctx *context.APIContext) {
534 | 	// swagger:operation POST /repos/{owner}/{repo}/issues issue issueCreateIssue
