537 | 	// consumes:
538 | 	// - application/json
539 | 	// produces:
540 | 	// - application/json
541 | 	// parameters:
542 | 	// - name: owner
543 | 	//   in: path
544 | 	//   description: owner of the repo
545 | 	//   type: string
546 | 	//   required: true
547 | 	// - name: repo
548 | 	//   in: path
549 | 	//   description: name of the repo
550 | 	//   type: string
551 | 	//   required: true
552 | 	// - name: body
553 | 	//   in: body
554 | 	//   schema:
555 | 	//     "$ref": "#/definitions/CreateIssueOption"
556 | 	// responses:
557 | 	//   "201":
558 | 	//     "$ref": "#/responses/Issue"
559 | 	//   "403":
560 | 	//     "$ref": "#/responses/forbidden"
561 | 	//   "404":
562 | 	//     "$ref": "#/responses/notFound"
