","bytes":4312},{"id":"ev-24711ef670bd00bfa7b8","repository":"go-gitea/gitea","sourceRef":"fc28937a8d772fe9e4025c9b5f24d5db4d86610b","path":"services/issue/issue.go","sha256":"632232e16929c6fa0a4b5c6e17aed3f52d4e5e372d8801793d2461ae42ee3c43","startLine":25,"endLine":84,"text":"25 | func NewIssue(ctx context.Context, repo *repo_model.Repository, issue *issues_model.Issue, labelIDs []int64, uuids []string, assigneeIDs, projectIDs []int64) error {
