			OldTitle:         opts.OldTitle,
			NewTitle:         opts.NewTitle,
			OldRef:           opts.OldRef,
			NewRef:           opts.NewRef,
			DependentIssueID: opts.DependentIssueID,
			TreePath:         opts.TreePath,
			ReviewID:         opts.ReviewID,
			Patch:            opts.Patch,
			RefRepoID:        opts.RefRepoID,
